def solveR(Gk):
    A=np.array(Gk); H,W=A.shape
    cnt=Counter(A.flatten().tolist()); bg=Counter(v for v in cnt if v!=0).most_common(1)[0][0]
    def dirs(): return ((0,1),(1,0),(-1,0),(0,-1))
