        v=int(A[r_,c_])
        for dr,dc in dirs():
            rr,cc=r_,c_; steps=[]
            while True:
                rr+=dr; cc+=dc
                if not(0<=rr<H and 0<=cc<W): break
                x=int(A[rr,cc])
                if x==v:
                    # reached same-color target -> fill path
                    for rr,cc in steps+[ (rr,cc) ]:
