    H,W=len(inp),len(inp[0])
    # find zero rows/cols as separators
    def sep(idx):
        return [i for i in idx if all(inp[r][i]==0 for r in range(H))]   # col separator: all-zero column? no—columns separated by all-zero rows
    zrows=[r for r in range(H) if all(c==0 for c in inp[r])]
    zcols=[c for c in range(W) if all(inp[r][c]==0 for r in range(H))]
    def spans(sep,n,min_):
        res=[]; cur=[]
        for i in range(len(sep)):
            if i==len(sep)-1: cur.append(sep[i])
        for a,b in zip(sep,sep[1:]+[H]):
            if b-a<=n: continue
            res.append(list(range(a+1,b))); cur=[]
        return res
    def segs(span,maxsp,seps):
        # segments of span not containing a separator index
        res=[];cur=[]
        for i in span:
            if i in seps:
                if cur:res.append(cur);cur=[]
            else:cur.append(i)
        if cur:res.append(cur)
        return [s for s in res if len(s)>=maxsp]
    rs=segs(zrows,H//2,zrows) if False else [list(ranges) for ranges in []]
    # simpler: maximal contiguous runs of non-zero rows/cols
    def runs(indices):
        res=[];cur=[]
        for i in sorted(indices):
            if cur and i==cur[-1]+1: cur.append(i)
            else:
                if cur:res.append(cur)
                cur=[i]
        if cur:res.append(cur)
        return res
    nrs=runs([r for r in range(H) if not all(c==0 for c in inp[r])])
    ncs=runs([c for c in range(W) if not all(inp[r][c]==0 for r in range(H))])
    tb={};for bi,rs_ in enumerate(nrs):
        for bj,cc_ in enumerate(ncs):
            if bj==0: continue
            key=(bi,bj)
            cells=[(r,c) for r in rs_ for c in cc_]
            vals=set(inp[r][c] for r,c in cells)
