        rs=[p[0] for p in cc]; cs=[p[1] for p in cc]
        r0,c0,r1,c1=min(rs),min(cs),max(rs),max(cs)
        if s<th:
            for (r,c) in cc: out[r,c]=bg
        elif (r1-r0+1)==(c1-c0+1) and s==th*0+0 and s in (1,4,9,16):
