import numpy as np
def f(a):
    h,w=a.shape; o=a.copy()
    for r in range(h):
        for c in range(w):
            vals=[int(o[r+dr,c+dc]) for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)] if 0<=r+dr<h and 0<=c+dc<w]
            if len(set(vals))==len(vals) and vals.count(o[r,c])==1 and 4==len(vals): continue
            if len(vals)>0:
                maj=Counter(vals).most_common(1)[0][0]
                if maj!=o[r,c]: o[r,c]=maj
    return o
