def clean(a, win):
    h,w=a.shape
    o=[row[:] for row in a]
    for _ in range(2):
        for r in range(h):
            for c in range(w):
                vals=[o[r+dr,c+dc] for dr in range(-win,win+1) for dc in range(-win,win+1)
                      if 0<=r+dr<h and 0<=c+dc<w and (dr,dc)!=(0,0)]
                o[r][c]=max(set(vals), key=vals.count)
    return o
