import numpy as np
def clean(a, win):
    o=[list(map(int,row)) for row in a]
    h,w=len(o),len(o[0])
    for _ in range(2):
        new=[[int(x) for x in row] for row in o]
        for r in range(h):
            for c in range(w):
                vals=[o[r+dr][c+dc] for dr in range(-win,win+1) for dc in range(-win,win+1)
                      if 0<=r+dr<h and 0<=c+dc<w and (dr,dc)!=(0,0)]
                new[r][c]=max(set(vals), key=vals.count)
        o=new
    return o
for n in range(1,9):
    a=np.array(G[f'Demo pair {n} input']); b=np.array(G[f'Demo pair {n} output'])
    for win in (1,2):
